    #[inline]
    fn call_route(
        &self,
        match_: matchit::Match<&RouteId>,
        mut req: Request<B>,
        state: S,
    ) -> RouteFuture<B, Infallible> {
        let id = *match_.value;

        #[cfg(feature = "matched-path")]
        crate::extract::matched_path::set_matched_path_for_request(
            id,
            &self.node.route_id_to_path,
            req.extensions_mut(),
        );

        url_params::insert_url_params(req.extensions_mut(), match_.params);

        let endpont = self
            .routes
            .get(&id)
            .expect("no route for id. This is a bug in axum. Please file an issue")
            .clone();

        match endpont {
            Endpoint::MethodRouter(mut method_router) => {
                let mut route = method_router.fallback_route(state.clone());
                route.call_with_state(&mut method_router, req, state)
            }
            Endpoint::Route(mut route) => route.call(req),
            Endpoint::NestedRouter(router) => router.call_with_state(req, state),
        }
    }
}

