    assert_eq!(hyper::body::to_bytes(res.into_body()).await.unwrap(), "fallback foo");

    let res = app
        .oneshot(Request::builder().method("POST").uri("/does-not-exist").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::NOT_FOUND);
    assert_eq!(hyper::body::to_bytes(res.into_body()).await.unwrap(), "not_found foo");
}
EOF
